class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        n = len(isConnected)
        visited = [False] * n

        def dfs(i: int) -> None:
            visited[i] = True
            for j in range(n):                   # scan row i of the matrix
                if isConnected[i][j] and not visited[j]:
                    dfs(j)

        provinces = 0
        for i in range(n):
            if not visited[i]:                   # a new component
                provinces += 1
                dfs(i)
        return provinces
